age seul. Unité extérieure WH-WXG09ME5 + module intérieur WH-SDC0916M3E5. Fluide frigorigène : R290. Topologie : hydrosplit (liaison hydraulique). Température de départ maximale : 75 °C. ETAS : 140 % à 55 °C et 197 % à 35 °C. SCOP : 3,58.", "caracteristiques": {"fiche_cee": "BAR-TH-171", "usage": "Chauffage seul", "temp": "Moyenne ou haute température", "etas": 140, "etas_55c_pct": 140.0, "etas_35c_pct": 197.0, "puissance_nominale_indiquee_kw": 9.0, "gamme": "Aquarea T-CAP Série M", "fluide_frigorigene": "R290", "topologie": "Hydrosplit (liaison hydraulique)", "alimentation_electrique": "Monophasé", "temperature_depart_max_c": 75, "unite_exterieure": "WH-WXG09ME5", "module_interieur": "WH-SDC0916M3E5", "reference_fabricant": "WH-WXG09ME5 + WH-SDC0916M3E5", "type_element": "pack", "aides_estimatives_a_verifier": true, "note_reglementaire": "Valeurs techniques reprises de la liste fournie. Classe du régulateur à renseigner d'après la fiche produit (UE) 811/2013 avant validation BAR-TH-171.", "scop": 3.58, "scop_source": 3.58, "gamme_source": "Haut de gamme", "prix_a_renseigner": true}}, {"nom": "Pack PAC air/eau Panasonic Aquarea T-CAP Série M 9 kW, chauffage seul, triphasé — WH-WXG09ME8 + WH-SDC0316M9E8, R290, liaison hydraulique, départ 75 °C, ETAS 140 % à 55 °C (197 % à 35 °C)", "marque": "Panasonic", "reference": "PANASONIC-WH-WXG09ME8-WH-SDC0316M9E8", "aliases": [], "pack": true, "prix_unitaire_ht": null, "description": "Pack pompe à chaleur air/eau Panasonic Aquarea T-CAP Série M 9 kW, triphasé, chauffage seul. Unité extérieure WH-WXG09ME8 + module intérieur WH-SDC0316M9E8. Fluide frigorigène : R290. Topologie : hydrosplit (liaison hydraulique). Température de départ maximale : 75 °C. ETAS : 140 % à 55 °C et 197 % à 35 °C. SCOP : 3,58.", "caracteristiques": {"fiche_cee": "BAR-TH-171", "usage": "Chauffage seul", "temp": "Moyenne ou haute température", "etas": 140, "etas_55c_pct": 140.0, "etas_35c_pct": 197.0, "puissance_nominale_indiquee_kw": 9.0, "gamme": "Aquarea T-CAP Série M", "fluide_frigorigene": "R290", "topologie": "Hydrosplit (liaison hydraulique)", "alimentation_electrique": "Triphasé", "temperature_depart_max_c": 75, "unite_exterieure": "WH-WXG09ME8", "module_interieur": "WH-SDC0316M9E8", "reference_fabricant": "WH-WXG09ME8 + WH-SDC0316M9E8", "type_element": "pack", "aides_estimatives_a_verifier": true, "note_reglementaire": "Valeurs techniques reprises de la liste fournie. Classe du régulateur à renseigner d'après la fiche produit (UE) 811/2013 avant validation BAR-TH-171.", "scop": 3.58, "scop_source": 3.58, "gamme_source": "Haut de gamme", "prix_a_renseigner": true}}]$produits$::jsonb));

  -- Fusion des doublons issus du fichier Excel du 20/10/2026.
  FOR d IN SELECT value FROM jsonb_array_elements($doublons$[{"marque": "Panasonic", "reference": "PANASONIC WH-UDZ05KE5 + WH-ADC0309K", "canon": "PANASONIC-WH-UDZ05KE5-WH-ADC0309K3E5"}]$doublons$::jsonb) LOOP
    SELECT id INTO v_canon FROM catalogue_produits
    WHERE categorie = 'pac_air_eau' AND reference = d->>'canon'
    ORDER BY actif DESC, created_at NULLS LAST LIMIT 1;
    CONTINUE WHEN v_canon IS NULL;

    FOR v_dup IN
      SELECT id, forfait_pose_ht, forfait_evacuation_ht, caracteristiques
      FROM catalogue_produits
      WHERE categorie = 'pac_air_eau' AND id <> v_canon
        AND marque = d->>'marque' AND reference = d->>'reference'
    LOOP
      UPDATE catalogue_produits SET
        forfait_pose_ht = CASE WHEN COALESCE(forfait_pose_ht, 0) > 0 THEN forfait_pose_ht ELSE COALESCE(v_dup.forfait_pose_ht, 0) END,
        forfait_evacuation_ht = CASE WHEN COALESCE(forfait_evacuation_ht, 0) > 0 THEN forfait_evacuation_ht ELSE COALESCE(v_dup.forfait_evacuation_ht, 0) END,
        caracteristiques = (COALESCE(v_dup.caracteristiques, '{}'::jsonb)
                              - 'fiche_cee'::text - 'source_tarifs'::text - 'source_date'::text
                              - 'prix_fourniture_ht'::text - 'forfait_pose_ht'::text - 'doublon_de'::text - 'ancienne_reference'::text)
                           || COALESCE(caracteristiques, '{}'::jsonb)
      WHERE id = v_canon;

      UPDATE catalogue_produits SET
        actif = false,
        caracteristiques = COALESCE(caracteristiques, '{}'::jsonb) || jsonb_build_object('doublon_de', d->>'canon')
      WHERE id = v_dup.id;
      v_doublons := v_doublons + 1;
    END LOOP;
    v_canon := NULL;
  END LOOP;

  RAISE NOTICE 'Panasonic : % ajouté(s), % mis à jour, % doublon(s) Excel fusionné(s)', v_ajoutes, v_maj, v_doublons;
END $$;
